`timescale 1ns/1ps
// Self-checking testbench for skid_buffer: lanes at WIDTH 8 and WIDTH 1,
// sharing the same handshake stimulus and one queue model.
module skid_buffer_tb;
    localparam integer W = 8;

    reg            clk;
    reg            rst_n;
    reg            s_valid;
    reg  [W-1:0]   s_data;
    reg            m_ready;

    wire           s_ready8;
    wire           m_valid8;
    wire [W-1:0]   m_data8;
    wire           s_ready1;
    wire           m_valid1;
    wire [0:0]     m_data1;

    skid_buffer #(.WIDTH(W)) dut8 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready8), .s_data(s_data),
        .m_valid(m_valid8), .m_ready(m_ready), .m_data(m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk(clk), .rst_n(rst_n),
        .s_valid(s_valid), .s_ready(s_ready1), .s_data(s_data[0:0]),
        .m_valid(m_valid1), .m_ready(m_ready), .m_data(m_data1)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    integer passed;
    integer failed;
    integer cnt;
    integer sent;
    integer recv;
    integer dropped;
    integer i;
    integer seed;
    integer th_s;
    integer th_m;
    reg            checking;
    reg  [W-1:0]   q [0:3];
    reg  [W-1:0]   head;
    reg            last_sfire;
    reg            last_mfire;
    reg            ps8;
    reg            ps1;
    reg            pend8;
    reg            pend1;
    reg  [W-1:0]   pd8;
    reg            pd1;
    reg  [W-1:0]   hd8;
    reg            hd1;
    reg  [31:0]    r;
    reg  [W-1:0]   val;
    reg            sv_r;
    reg            mr_r;
    reg  [8*64-1:0] nonce;

    task check;
        input          ok;
        input [8*64-1:0] what;
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL: %0s at %0t", what, $time);
            end
        end
    endtask

    // Outputs against the model, before the edge.
    task check_outputs;
        begin
            check(m_valid8 === (cnt > 0), "m_valid (W8) high exactly while beats held");
            check(s_ready8 === (cnt < 2), "s_ready (W8) high exactly while < 2 held");
            check(m_valid1 === (cnt > 0), "m_valid (W1) high exactly while beats held");
            check(s_ready1 === (cnt < 2), "s_ready (W1) high exactly while < 2 held");
            if (cnt > 0) begin
                head = q[0];
                check(m_data8 === head, "m_data (W8) is the oldest beat");
                check(m_data1[0] === head[0], "m_data (W1) is the oldest beat");
            end
            if (pend8) begin
                check(m_valid8 === 1'b1, "hold: stalled beat stays offered (W8)");
                check(m_data8 === pd8, "hold: stalled data unchanged (W8)");
            end
            if (pend1) begin
                check(m_valid1 === 1'b1, "hold: stalled beat stays offered (W1)");
                check(m_data1[0] === pd1, "hold: stalled data unchanged (W1)");
            end
            check(cnt <= 2, "slice never holds more than two beats");
        end
    endtask

    // Outputs must not move when inputs change inside a cycle.
    task glitch_check;
        reg sr8;
        reg mv8;
        reg sr1;
        reg mv1;
        reg [W-1:0] md8;
        reg md1;
        begin
            sr8 = s_ready8; mv8 = m_valid8; md8 = m_data8;
            sr1 = s_ready1; mv1 = m_valid1; md1 = m_data1[0];
            s_valid = ~s_valid; m_ready = ~m_ready; s_data = ~s_data;
            #1;
            check(s_ready8 === sr8, "s_ready (W8) ignores inputs within a cycle");
            check(m_valid8 === mv8 && m_data8 === md8, "m outputs (W8) ignore inputs within cycle");
            check(s_ready1 === sr1, "s_ready (W1) ignores inputs within a cycle");
            check(m_valid1 === mv1 && m_data1[0] === md1, "m outputs (W1) ignore inputs within cycle");
            s_valid = ~s_valid; m_ready = ~m_ready; s_data = ~s_data;
            #1;
        end
    endtask

    // One clock cycle: apply inputs, check, take the edge, update the model.
    task step;
        input          sv;
        input [W-1:0]  sd;
        input          mr;
        begin
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            #1;
            if (checking) begin
                check_outputs;
                glitch_check;
            end
            last_sfire = s_valid & s_ready8;
            last_mfire = m_valid8 & m_ready;
            ps8 = m_valid8 & ~m_ready;
            pd8 = m_data8;
            ps1 = m_valid1 & ~m_ready;
            pd1 = m_data1[0];
            hd8 = s_data;
            @(posedge clk);
            if (rst_n === 1'b0) begin
                dropped  = dropped + cnt;
                cnt      = 0;
                checking = 1'b1;
                pend8    = 1'b0;
                pend1    = 1'b0;
            end else if (checking) begin
                pend8 = ps8;
                pend1 = ps1;
                if (last_mfire === 1'b1) begin
                    if (cnt > 0) begin
                        q[0] = q[1];
                        q[1] = q[2];
                        q[2] = q[3];
                        cnt  = cnt - 1;
                        recv = recv + 1;
                    end else begin
                        check(1'b0, "beat taken while the model is empty");
                    end
                end
                if (last_sfire === 1'b1) begin
                    if (cnt < 4) begin
                        q[cnt] = hd8;
                        cnt    = cnt + 1;
                        sent   = sent + 1;
                    end else begin
                        check(1'b0, "beat accepted with the model full");
                    end
                end
            end
            #1;
        end
    endtask

    task drain;
        begin
            repeat (4) step(1'b0, {W{1'b0}}, 1'b1);
            check(cnt == 0, "drain: model empty");
            check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "drain: m_valid low");
            check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "drain: s_ready high");
            check(sent == recv + dropped, "drain: every accepted beat out exactly once");
        end
    endtask

    initial begin
        passed = 0; failed = 0; cnt = 0; sent = 0; recv = 0; dropped = 0;
        checking = 1'b0; pend8 = 1'b0; pend1 = 1'b0;
        seed = 24301; val = {W{1'b0}};
        last_sfire = 1'b0; last_mfire = 1'b0;
        s_valid = 1'b0; s_data = {W{1'b0}}; m_ready = 1'b0; rst_n = 1'b0;
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
            nonce = "unset";

        // Reset values (sender offers beats during reset).
        step(1'b1, 8'h11, 1'b1);
        step(1'b1, 8'h12, 1'b0);
        rst_n = 1'b1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset: m_valid low");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset: s_ready high");

        // One-cycle latency.
        step(1'b1, 8'hA5, 1'b1);
        check(last_sfire === 1'b1, "latency: beat accepted");
        check(m_valid8 === 1'b1 && m_data8 === 8'hA5, "latency: offered one cycle after accept (W8)");
        check(m_valid1 === 1'b1 && m_data1[0] === 1'b1, "latency: offered one cycle after accept (W1)");
        step(1'b0, 8'h00, 1'b1);
        check(last_mfire === 1'b1, "latency: beat taken");
        check(m_valid8 === 1'b0, "latency: empty after the single beat");

        // Full throughput, long stream.
        for (i = 0; i < 64; i = i + 1) begin
            val = val + 8'd1;
            step(1'b1, val, 1'b1);
            check(last_sfire === 1'b1, "throughput: beat accepted on every edge");
            if (i > 0)
                check(last_mfire === 1'b1, "throughput: beat leaves on every edge");
        end
        drain;

        // Stall with one beat held, then with two.
        step(1'b1, 8'h31, 1'b0);
        check(last_sfire === 1'b1, "stall: first beat accepted");
        step(1'b1, 8'h32, 1'b0);
        check(last_sfire === 1'b1, "stall: second beat accepted with one held");
        check(s_ready8 === 1'b0 && s_ready1 === 1'b0, "stall: s_ready low with two held");
        step(1'b1, 8'h33, 1'b0);
        check(last_sfire === 1'b0, "stall: third beat refused");
        step(1'b1, 8'h34, 1'b0);
        check(last_sfire === 1'b0, "stall: changed data still refused");
        step(1'b0, 8'h00, 1'b0);
        repeat (4) step(1'b1, 8'h35, 1'b0);
        check(m_data8 === 8'h31, "stall: oldest beat still offered");

        // Ready rises after the stall.
        step(1'b1, 8'h35, 1'b1);
        check(last_mfire === 1'b1 && last_sfire === 1'b0, "release: oldest leaves, input refused");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "release: s_ready rises after a beat leaves");
        check(m_data8 === 8'h32, "release: second beat offered next");
        step(1'b1, 8'h36, 1'b1);
        check(last_mfire === 1'b1 && last_sfire === 1'b1, "release: no bubble after skid empties");
        check(m_data8 === 8'h36, "release: new beat follows in order");
        drain;

        // Single-cycle stalls inside a stream.
        for (i = 0; i < 40; i = i + 1) begin
            val = val + 8'd1;
            step(1'b1, val, ((i % 5) != 3));
        end
        drain;

        // Multi-cycle stalls inside a stream.
        for (i = 0; i < 40; i = i + 1) begin
            val = val + 8'd1;
            step(1'b1, val, ((i % 10) < 6));
        end
        drain;

        // Sender bubbles with receiver always ready.
        for (i = 0; i < 20; i = i + 1) begin
            val = val + 8'd1;
            step(((i % 3) != 0), val, 1'b1);
        end
        drain;

        // Reset with beats held.
        step(1'b1, 8'h41, 1'b0);
        step(1'b1, 8'h42, 1'b0);
        check(cnt == 2 && m_valid8 === 1'b1 && s_ready8 === 1'b0, "reset-held: two beats held");
        rst_n = 1'b0;
        step(1'b1, 8'h43, 1'b1);
        rst_n = 1'b1;
        check(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset-held: m_valid low after reset");
        check(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset-held: s_ready high after reset");
        step(1'b1, 8'h44, 1'b1);
        check(last_sfire === 1'b1, "reset-held: accepts after reset");
        check(m_valid8 === 1'b1 && m_data8 === 8'h44, "reset-held: new beat offered after reset");
        drain;

        // Random traffic against the model, with one reset mid-traffic.
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random(seed);
            case ((i / 250) % 4)
                0:       begin th_s = 12; th_m = 12; end
                1:       begin th_s = 16; th_m = 3;  end
                2:       begin th_s = 5;  th_m = 16; end
                default: begin th_s = 16; th_m = 16; end
            endcase
            sv_r = ({28'd0, r[3:0]} < th_s);
            mr_r = ({28'd0, r[7:4]} < th_m);
            rst_n = (i == 1777) ? 1'b0 : 1'b1;
            step(sv_r, r[15:8], mr_r);
        end
        rst_n = 1'b1;
        drain;
        check(recv > 1000, "random: traffic actually flowed");

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
